from gpio import * from time import * from ioeclient import * from physical import * from environment import * import math FAN_SPEED_LOW = 0.4; # kph FAN_SPEED_HIGH = 0.8; # kph COOLING_RATE = float(-1)/3600; # -1C/hour HUMDITY_REDUCTION_RATE = float(-1)/3600; # -1%/hour
VOLUME_AT_RATE = 100000; # the given rates are based on this volume
state = 0; # 0 off, 1 low, 2 high level = 0
def main(): global state IoEClient.setup({ "type": "Ceiling Fan", "states": [ { "name": "Status", "type": "options", "options": { "0": "Off", "1": "Low", "2": "High" }, "controllable": True } ] })
IoEClient.onInputReceive(onInputReceiveDone) add_event_detect(0, detect) state = restoreProperty("state", 0) setState(state) while True: delay(1000)
def onInputReceiveDone(data): processData(data, True)
def detect(): processData(customRead(0), False)
def restoreProperty(propertyName, defaultValue): value = getDeviceProperty(getName(), propertyName) if not (value is "" or value is None): if type(defaultValue) is int : value = int(value)
setDeviceProperty(getName(), propertyName, value) return value return defaultValue
def mouseEvent(pressed, x, y, firstPress): if firstPress: toggleState()
def processData(data, bIsRemote): if len(data) <= 0 : return data = data.split(",") setState(int(data[0]))
def sendReport(): global state global report report = state # comma seperated states customWrite(0, report) IoEClient.reportStates(report) setDeviceProperty(getName(), "state", state)
def setState(newState): global state analogWrite(A1, newState) state = newState
sendReport() updateEnvironment()
def toggleState(): global state state += 1 if int(state) >= 3: state = 0
setState(state)
def updateEnvironment(): global VOLUME_AT_RATE global FAN_SPEED_LOW global COOLING_RATE global HUMDITY_REDUCTION_RATE global FAN_SPEED_HIGH global state volumeRatio = float(VOLUME_AT_RATE) / Environment.getVolume()
if int(state) == 0: Environment.setContribution("Wind Speed", 0, 0, True) Environment.setContribution("Ambient Temperature", 0, 0, True) Environment.setContribution("Humidity", 0,0, True)
elif int(state) == 1: Environment.setContribution("Wind Speed", FAN_SPEED_LOW, FAN_SPEED_LOW, False)
# everytime the fan restarts, it can do another -100C Environment.setContribution("Ambient Temperature", float(COOLING_RATE)/2*volumeRatio, Environment.getCumulativeContribution("Ambient Temperature")-100, True)
Environment.setContribution("Humidity", float(HUMDITY_REDUCTION_RATE)/2*volumeRatio, Environment.getCumulativeContribution("Humidity")-100, True) elif int(state) == 2: Environment.setContribution("Wind Speed", FAN_SPEED_HIGH, FAN_SPEED_HIGH, False)
Environment.setContribution("Ambient Temperature", float(COOLING_RATE)/2*volumeRatio, Environment.getCumulativeContribution("Ambient Temperature")-100, True)
Environment.setContribution("Humidity", HUMDITY_REDUCTION_RATE*volumeRatio, Environment.getCumulativeContribution("Humidity")-100, True)
if __name__ == "__main__": main()

var FAN_SPEED_LOW = 0.4; // kph
var FAN_SPEED_HIGH = 0.8; // kph
var COOLING_RATE = -1/3600; // -1C/hour
var HUMDITY_REDUCTION_RATE = -1/3600; // -1%/hour

var VOLUME_AT_RATE = 100000;	// the given rates are based on this volume

var state = 0;	// 0 off, 1 low, 2 high
var level = 0;

function setup() {

	IoEClient.setup({
		type: "Ceiling Fan",
		states: [
		{
			name: "Status",
			type: "options",
			options: {
				"0": "Off",
				"1": "Low",
				"2": "High"
			},
			controllable: true
		}			
		]
	});

	IoEClient.onInputReceive = function(input) {
		processData(input, true);
	};

	attachInterrupt(0, function() {
		processData(customRead(0), false);
	});

	state = restoreProperty("state", 0);
	setState(state);
}

function restoreProperty(propertyName, defaultValue)
{
	var value = getDeviceProperty(getName(), propertyName);
	if ( !(value === "" || value == "undefined") ){
		if ( typeof(defaultValue) == "number" )
			value = Number(value);

		setDeviceProperty(getName(), propertyName, value);
		return value;
	}

	return defaultValue;
}

function mouseEvent(pressed, x, y, firstPress) {
	if (firstPress)
		toggleState();
}

function processData(data, bIsRemote)
{
	if ( data.length <= 0  )
		return;
	data = data.split(",");
	setState(parseInt(data[0]));
}

function sendReport()
{
	var report = state;	// comma seperated states
	customWrite(0, report);
	IoEClient.reportStates(report);
	setDeviceProperty(getName(), "state", state);
}

function setState(newState)
{
	analogWrite(A1, newState);
	state = newState;

	sendReport();
	updateEnvironment();
}

function toggleState()
{
	++state;
	if ( state >= 3 )
		state = 0;

	setState(state);


}

function updateEnvironment()
{
	var volumeRatio = VOLUME_AT_RATE / Environment.getVolume();

	if ( state === 0){
		Environment.setContribution("Wind Speed", 0, 0);
		Environment.setContribution("Ambient Temperature", 0, 0);
		Environment.setContribution("Humidity", 0,0); 
	}
	else if ( state == 1 )
	{
		Environment.setContribution("Wind Speed", FAN_SPEED_LOW, FAN_SPEED_LOW, false);

		// everytime the fan restarts, it can do another -100C
		Environment.setContribution("Ambient Temperature", COOLING_RATE/2*volumeRatio, 
			Environment.getCumulativeContribution("Ambient Temperature")-100);

		Environment.setContribution("Humidity", HUMDITY_REDUCTION_RATE/2*volumeRatio, 
			Environment.getCumulativeContribution("Humidity")-100);

	}
	else if ( state == 2)
	{
		Environment.setContribution("Wind Speed", FAN_SPEED_HIGH, FAN_SPEED_HIGH, false);

		Environment.setContribution("Ambient Temperature", COOLING_RATE/2*volumeRatio, 
			Environment.getCumulativeContribution("Ambient Temperature")-100);

		Environment.setContribution("Humidity", HUMDITY_REDUCTION_RATE*volumeRatio, 
			Environment.getCumulativeContribution("Humidity")-100);
	}



}

