var COOLER_PIN = 2;
var state = 0;	// 0 off, 1 cooling, 2 heating, 3 auto
var STATE_NAMES = ["OFF", "COOL", "HEAT", "AUTO"];
var temperature = 0;
var unit;


function setup () {
	IoEClient.setup({
		type: "Thermostat",
		states: [{
			name: "Status",
			type: "options",
			options: {
				"0": "Off",
				"1": "Cooling",
				"2": "Heating",
				"3": "Auto"
			},
			controllable: true
		}, {
			name: "Temperature",
			type: "number",
			unit: "&deg;C",
			imperialUnit: "&deg;F",
			toImperialConversion: "x*1.8+32",
			toMetricConversion: "(x-32)/1.8",
			decimalDigits: 1
		}, {
			name: "Auto Cool Temperature",
			type: "number",
			unit: "&deg;C",
			imperialUnit: "&deg;F",
			toImperialConversion: "x*1.8+32",
			toMetricConversion: "(x-32)/1.8",
			decimalDigits: 1,
			controllable: true,
			minValue: 10,
			maxValue: 100
		}, {
			name: "Auto Heat Temperature",
			type: "number",
			unit: "&deg;C",
			imperialUnit: "&deg;F",
			toImperialConversion: "x*1.8+32",
			toMetricConversion: "(x-32)/1.8",
			decimalDigits: 1,
			controllable: true,
			minValue: -100,
			maxValue: 20
		}]
	});

	IoEClient.onInputReceive = function(input) {
		processData(input, true);
	};

	attachInterrupt(0, function() {
		processData(customRead(0), false);
	});


	temperature = Environment.get("Ambient Temperature");

	measurementSystemChangeEvent();

	state = restoreProperty("state", 0);
	setState(state);

	autoCoolTemp = restoreProperty("auto cool temp", 20);
	autoHeatTemp = restoreProperty("auto heat temp", 19);




	Environment.removeCumulativeContribution("Ambient Temperature");

	updateEnvironment();
	sendReport();
	processData(customRead(0), false);
}

function restoreProperty (propertyName, defaultValue) {
	var value = getDeviceProperty(getName(), propertyName);
	if ( !(value === "" || value == "undefined") ) {
		if ( typeof(defaultValue) == "number" ) {
			value = Number(value);
        }

		setDeviceProperty(getName(), propertyName, value);
		return value;
	}

	return defaultValue;
}


function loop () {

	temperature = Environment.get("Ambient Temperature");
	updateEnvironment();
	measurementSystemChangeEvent();
	sendReport();
	delay(1000);
}

function measurementSystemChangeEvent () {
	METRIC = isUsingMetric();
	unit = METRIC ? "C" : "F";
	setCustomText(27, 15, 200, 100,
		STATE_NAMES[state] + "  " +
		convertTemperature(temperature) + " " + unit);		
}

function mouseEvent (pressed, x, y, firstPress) {
	// if mouse pressed, then flip it
	if (firstPress) {
		state++;
		if (state >= 4) {
			state = 0;
        }

		setState(state);
	}
}

function processData (data, bIsRemote) {
	if (data) {
		data = data.split(",");

		setState(parseInt(data[0]));
		autoCoolTemp = parseFloat(data[2]);
		autoHeatTemp = parseFloat(data[3]);
		if(autoHeatTemp > autoCoolTemp) {
			var t = autoCoolTemp
			autoCoolTemp = autoHeatTemp
			autoHeatTemp = t
		}
	}
}

function setState (newState) {
	state = newState;

	analogWrite(A1, state); // change graphic
	setCustomText(27, 15, 200, 100,
		STATE_NAMES[state] + "  " +
		convertTemperature(temperature) + " " + unit);		

	sendReport();

}

function sendReport () {
	var report = state + "," + temperature + ","
		+ autoCoolTemp + "," + autoHeatTemp;
	customWrite(0, report);
	IoEClient.reportStates(report);
	setDeviceProperty(getName(), "state", state);
	setDeviceProperty(getName(), "temperature", temperature);
	setDeviceProperty(getName(), "auto cool temp", autoCoolTemp);
	setDeviceProperty(getName(), "auto heat temp", autoHeatTemp);
}

function updateEnvironment ()
{
	var autoCoolTemp = getDeviceProperty(getName(), "auto cool temp");
	var autoHeatTemp = getDeviceProperty(getName(), "auto heat temp");

	digitalWrite(HEATER_PIN, LOW);
	digitalWrite(COOLER_PIN, LOW);

	if ( state === 0 ) {
		digitalWrite(HEATER_PIN, LOW);
		digitalWrite(COOLER_PIN, LOW);
	}
	else if ( state === 1 ) {
		digitalWrite(COOLER_PIN, HIGH);
	}
	else if ( state == 2 ) {
		digitalWrite(HEATER_PIN, HIGH);
	}
	else if ( state == 3 ) {
        if( temperature >= autoCoolTemp)
            digitalWrite(COOLER_PIN, HIGH);
        else if( temperature <= autoHeatTemp )
            digitalWrite(HEATER_PIN, HIGH);
	}
}

function convertTemperature (value) {
	if (METRIC) {
		return value.toFixed(0);
    } else {
		return (value * 1.8 + 32).toFixed(0);
    }
}

from gpio import *
from time import *
from ioeclient import *
from physical import *
import math
from environment import *

ENVIRONMENT_NAME = "Smoke"

state = 0
level = 0
ALARM_LEVEL = 40

def main():
    setup()
    while True:
		loop()

def setup():
    IoEClient.setup({
        "type": "Smoke Detector",
        "states": [{
            "name": "Alarm",
            "type": "bool",
            "controllable": False
        },
        {
            "name": "Level",
            "type": "number",
            "controllable": False
        }]
    })

    restoreProperty("Alarm Level", 40)
    IoEClient.onInputReceive(onInputReceiveDone)
    add_event_detect(0, detect)

    state = restoreProperty("state", 0)
    setState(state)

def onInputReceiveDone(data):
    processData(data, True)

def detect():
    processData(customRead(0), False)

def restoreProperty(propertyName, defaultValue):
    value = getDeviceProperty(getName(), propertyName)
    if  not (value is "" or value is None):
        if  type(defaultValue) is int :
            value = int(value)

        setDeviceProperty(getName(), propertyName, value)
        return value
    return defaultValue

def loop():
    global ENVIRONMENT_NAME
    value = Environment.get(ENVIRONMENT_NAME)
    if value >= 0:
        setLevel(Environment.get(ENVIRONMENT_NAME))
    #print(value)
    sleep(1)


def processData(data, bIsRemote):
    if len(data) <= 0 :
        return
    data = data.split(",")
    setState(int(data[0]))


def sendReport():
    global state
    global level
    report = str(state) + "," + str(level);   # comma seperated states
    IoEClient.reportStates(report)
    setDeviceProperty(getName(), "state", state)
    setDeviceProperty(getName(), "level", level)


def setState(newState):
    global state
    state = newState

    if newState is 0:
        digitalWrite(1, LOW)
    else:
        digitalWrite(1, HIGH)

    sendReport()


def setLevel(newLevel):
    global level
    if level == newLevel:
        return

    level = newLevel
    if level > ALARM_LEVEL:
        setState(1)
    else:
        setState(0)

    sendReport()

if __name__ == "__main__":
    main()

