from gpio import * from time import * from ioeclient import * from physical import * from environment import * import math
ENVIRONMENTS = ["Argon", "CO", "CO2", "Hydrogen", "Helium", "Methane", "Nitrogen", "O2", "Ozone", "Propane", "Smoke"] ENVIRONMENT_MAX_IMPACT = -0.01; # 2% max when door opens TEMPERATURE_TRANSFERENCE_MULTIPLIER = 1.20; # increase speed 25% when door open HUMIDITY_TRANSFERENCE_MULTIPLIER = 1.20 GASES_TRANSFERENCE_MULTIPLIER = 2
state = 0
def main(): setup() while True: loop() #set up client to talk and listen to IoE registration server def setup(): IoEClient.setup({ "type": "Window", "states": [{ "name": "On", "type": "bool", "controllable": True }] })
IoEClient.onInputReceive(onInputReceiveDone) add_event_detect(0, detect)
state = restoreProperty("state", 0) setState(state)
def onInputReceiveDone(data): processData(data, True)
def detect(): processData(customRead(0), false)
def restoreProperty(propertyName, defaultValue): value = getDeviceProperty(getName(), propertyName) if not (value is "" or value is None): if type(defaultValue) is int : value = int(value)
setDeviceProperty(getName(), propertyName, value) return value return defaultValue
def mouseEvent(pressed, x, y, firstPress): global state if firstPress: if state == True: setState(0) else: setState(1)
