#process data received from server def processData(data, bIsRemote): if len(data) <= 0 : return data = data.split(",") setState(int(data[0]))
#set state and update component image to reflect the current state def setState(newState): global state if newState is 0 : digitalWrite(1, LOW) else: digitalWrite(1, HIGH)
state = newState customWrite(0, state) IoEClient.reportStates(state) setDeviceProperty(getName(), "state", state)
def updateEnvironment(): global ENVIRONMENTS global ENVIRONMENT_MAX_IMPACT global GASES_TRANSFERENCE_MULTIPLIER global TEMPERATURE_TRANSFERENCE_MULTIPLIER global HUMIDITY_TRANSFERENCE_MULTIPLIER global state
if state == 1: for i in range (0,len(ENVIRONMENTS)): max = Environment.get(ENVIRONMENTS[i]) * ENVIRONMENT_MAX_IMPACT # the max is reached in an hour, so we divide by 3600 to get seconds # then this rate is also based on 100,000 cubic meters (approx. coporate office size) rate = float(max) / 3600 * 100000 / Environment.getVolume() Environment.setContribution(ENVIRONMENTS[i], rate, max, True) Environment.setTransferenceMultiplier(ENVIRONMENTS[i], GASES_TRANSFERENCE_MULTIPLIER)
