def main(): pinMode(0, IN) pinMode(1, IN) pinMode(2, OUT)
h, m = 6, 15 used = False
while True: motion = digitalRead(0) button = digitalRead(1)
if ((motion and 6 <= h < 10) or button) and not used: digitalWrite(2, HIGH) sleep(10) digitalWrite(2, LOW) used = True
if not motion and not button: used = False
sleep(1) m += 1 if m >= 60: m = 0 h = (h + 1) % 24
